def choose_move(observation):
    # Defensive field access with defaults
    env = observation.get("environment_name", "resource_collection")
    sx, sy = observation.get("self_position", (0, 0))
    ox, oy = observation.get("opponent_position", (0, 0))

    # Helper to compute step towards target
    def step_towards(tx, ty, sx, sy):
        dx = 0 if tx == sx else (1 if tx > sx else -1)
        dy = 0 if ty == sy else (1 if ty > sy else -1)
        return [dx, dy]

    # Pursuit-Evasion
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_towards(ox, oy, sx, sy)

        # Evader: move toward farthest corner from pursuer (robust fallback)
        grid_h = observation.get("grid_height", 0)
        grid_w = observation.get("grid_width", 0)

        corners = []
        if grid_w and grid_h:
            corners = [
                [0, 0],
                [0, grid_h - 1],
                [grid_w - 1, 0],
                [grid_w - 1, grid_h - 1],
            ]
        if not corners:
            return step_towards(ox, oy, sx, sy)

        # pick corner maximizing manhattan distance to pursuer
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return step_towards(target[0], target[1], sx, sy)

    # Territory control
    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if not targets:
            return [0, 0]
        best = min(targets, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
        return step_towards(best[0], best[1], sx, sy)

    # Resource collection (default)
    resources = observation.get("resources") or []
    if not resources:
        return step_towards(ox, oy, sx, sy)

    best = min(resources, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
    return step_towards(best[0], best[1], sx, sy)

